INSERT INTO sys_interface_service_change (
    id, task_id, service_id, change_type, service_name, direction, purpose, caller_name,
    authorization_scope, authorization_scope_value, owner_id, target_status
) VALUES (
    #{change.id}, #{change.taskId}, #{change.serviceId, jdbcType=BIGINT}, #{change.changeType},
    #{change.serviceName, jdbcType=VARCHAR}, #{change.direction, jdbcType=VARCHAR},
    #{change.purpose, jdbcType=VARCHAR}, #{change.callerName, jdbcType=VARCHAR},
    #{change.authorizationScope, jdbcType=VARCHAR}, #{change.authorizationScopeValue, jdbcType=VARCHAR},
    #{change.ownerId, jdbcType=BIGINT}, #{change.targetStatus, jdbcType=VARCHAR}
)

mapper.select:
SELECT change_record.id AS change_id, change_record.task_id, change_record.service_id, change_record.change_type, COALESCE(change_record.service_name, service.service_name) AS service_name, change_record.direction, change_record.purpose, change_record.caller_name, change_record.authorization_scope, change_record.authorization_scope_value, change_record.owner_id, change_record.target_status, task.task_title, task.task_description, task.status AS task_status, task.submitted_by, task.submitted_at, task.reviewed_by, task.reviewed_at, task.review_comment, change_record.created_at AS change_created_at FROM sys_interface_service_change change_record JOIN sys_system_task task ON task.id = change_record.task_id LEFT JOIN sys_interface_service service ON service.id = change_record.service_id
WHERE task.status = 'PENDING_REVIEW'
ORDER BY change_record.created_at DESC, change_record.id DESC LIMIT #{limit}
